// energy/degradation sketch for: Energy System Co-Simulator
let c = 1.0; const samples = [];
for (let i = 0; i < 552; i++) { c *= 0.99969; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 552, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

